-- Scoped network uniqueness (write guards, not unique indexes).
-- Networks: unique per (site_id, vlan_id or NULL = untagged scope, canonical IPv4 CIDR).
-- IP allocations: unique per (network_id, ip_address).
-- Triggers only guard new writes and only fire when a key column actually
-- changes; existing (possibly duplicated) rows are never scanned, altered or
-- deleted, and unrelated updates to legacy-duplicate rows keep working.
-- Canonical key = (ip & mask) * 64 + prefix; unparseable subnets (incl. leading-zero
-- octets, which isValidCIDR rejects) yield NULL
-- (never conflict). Note: FK SET NULL on VLAN delete is an UPDATE of vlan_id
-- and is therefore also guarded.

CREATE TRIGGER "Network_scoped_subnet_conflict_insert"
BEFORE INSERT ON "Network"
BEGIN
  SELECT RAISE(ABORT, 'NETWORK_SUBNET_CONFLICT')
  WHERE EXISTS (
    SELECT 1 FROM "Network" n
    WHERE n.id <> NEW.id AND n.site_id = NEW.site_id AND n.vlan_id IS NEW.vlan_id
      AND (SELECT CASE WHEN (s GLOB '[0-9]*.[0-9]*.[0-9]*.[0-9]*/[0-9]*' AND s NOT GLOB '*[^0-9./]*' AND s NOT GLOB '*..*' AND s NOT GLOB '*./*' AND s NOT GLOB '*/*[./]*' AND length(s)-length(replace(s,'.',''))=3 AND length(s)-length(replace(s,'/',''))=1 AND o1 <> '' AND o2 <> '' AND o3 <> '' AND o4 <> '' AND o1 = CAST(CAST(o1 AS INTEGER) AS TEXT) AND o2 = CAST(CAST(o2 AS INTEGER) AS TEXT) AND o3 = CAST(CAST(o3 AS INTEGER) AS TEXT) AND o4 = CAST(CAST(o4 AS INTEGER) AS TEXT) AND length(o1)<=3 AND length(o2)<=3 AND length(o3)<=3 AND length(o4)<=3 AND CAST(o1 AS INTEGER)<=255 AND CAST(o2 AS INTEGER)<=255 AND CAST(o3 AS INTEGER)<=255 AND CAST(o4 AS INTEGER)<=255 AND p<=32) THEN (((CAST(o1 AS INTEGER)*16777216+CAST(o2 AS INTEGER)*65536+CAST(o3 AS INTEGER)*256+CAST(o4 AS INTEGER)) & ((4294967295 << (32-p)) & 4294967295))*64+p) END FROM (SELECT s, o1, o2, o3, substr(r3,1,instr(r3,'/')-1) AS o4, CAST(substr(r3,instr(r3,'/')+1) AS INTEGER) AS p FROM (SELECT s, o1, o2, substr(r2,1,instr(r2,'.')-1) AS o3, substr(r2,instr(r2,'.')+1) AS r3 FROM (SELECT s, o1, r1, substr(r1,1,instr(r1,'.')-1) AS o2, substr(r1,instr(r1,'.')+1) AS r2 FROM (SELECT s, substr(s,1,instr(s,'.')-1) AS o1, substr(s,instr(s,'.')+1) AS r1 FROM (SELECT n.subnet AS s)))))) IS (SELECT CASE WHEN (s GLOB '[0-9]*.[0-9]*.[0-9]*.[0-9]*/[0-9]*' AND s NOT GLOB '*[^0-9./]*' AND s NOT GLOB '*..*' AND s NOT GLOB '*./*' AND s NOT GLOB '*/*[./]*' AND length(s)-length(replace(s,'.',''))=3 AND length(s)-length(replace(s,'/',''))=1 AND o1 <> '' AND o2 <> '' AND o3 <> '' AND o4 <> '' AND o1 = CAST(CAST(o1 AS INTEGER) AS TEXT) AND o2 = CAST(CAST(o2 AS INTEGER) AS TEXT) AND o3 = CAST(CAST(o3 AS INTEGER) AS TEXT) AND o4 = CAST(CAST(o4 AS INTEGER) AS TEXT) AND length(o1)<=3 AND length(o2)<=3 AND length(o3)<=3 AND length(o4)<=3 AND CAST(o1 AS INTEGER)<=255 AND CAST(o2 AS INTEGER)<=255 AND CAST(o3 AS INTEGER)<=255 AND CAST(o4 AS INTEGER)<=255 AND p<=32) THEN (((CAST(o1 AS INTEGER)*16777216+CAST(o2 AS INTEGER)*65536+CAST(o3 AS INTEGER)*256+CAST(o4 AS INTEGER)) & ((4294967295 << (32-p)) & 4294967295))*64+p) END FROM (SELECT s, o1, o2, o3, substr(r3,1,instr(r3,'/')-1) AS o4, CAST(substr(r3,instr(r3,'/')+1) AS INTEGER) AS p FROM (SELECT s, o1, o2, substr(r2,1,instr(r2,'.')-1) AS o3, substr(r2,instr(r2,'.')+1) AS r3 FROM (SELECT s, o1, r1, substr(r1,1,instr(r1,'.')-1) AS o2, substr(r1,instr(r1,'.')+1) AS r2 FROM (SELECT s, substr(s,1,instr(s,'.')-1) AS o1, substr(s,instr(s,'.')+1) AS r1 FROM (SELECT NEW.subnet AS s))))))
      AND (SELECT CASE WHEN (s GLOB '[0-9]*.[0-9]*.[0-9]*.[0-9]*/[0-9]*' AND s NOT GLOB '*[^0-9./]*' AND s NOT GLOB '*..*' AND s NOT GLOB '*./*' AND s NOT GLOB '*/*[./]*' AND length(s)-length(replace(s,'.',''))=3 AND length(s)-length(replace(s,'/',''))=1 AND o1 <> '' AND o2 <> '' AND o3 <> '' AND o4 <> '' AND o1 = CAST(CAST(o1 AS INTEGER) AS TEXT) AND o2 = CAST(CAST(o2 AS INTEGER) AS TEXT) AND o3 = CAST(CAST(o3 AS INTEGER) AS TEXT) AND o4 = CAST(CAST(o4 AS INTEGER) AS TEXT) AND length(o1)<=3 AND length(o2)<=3 AND length(o3)<=3 AND length(o4)<=3 AND CAST(o1 AS INTEGER)<=255 AND CAST(o2 AS INTEGER)<=255 AND CAST(o3 AS INTEGER)<=255 AND CAST(o4 AS INTEGER)<=255 AND p<=32) THEN (((CAST(o1 AS INTEGER)*16777216+CAST(o2 AS INTEGER)*65536+CAST(o3 AS INTEGER)*256+CAST(o4 AS INTEGER)) & ((4294967295 << (32-p)) & 4294967295))*64+p) END FROM (SELECT s, o1, o2, o3, substr(r3,1,instr(r3,'/')-1) AS o4, CAST(substr(r3,instr(r3,'/')+1) AS INTEGER) AS p FROM (SELECT s, o1, o2, substr(r2,1,instr(r2,'.')-1) AS o3, substr(r2,instr(r2,'.')+1) AS r3 FROM (SELECT s, o1, r1, substr(r1,1,instr(r1,'.')-1) AS o2, substr(r1,instr(r1,'.')+1) AS r2 FROM (SELECT s, substr(s,1,instr(s,'.')-1) AS o1, substr(s,instr(s,'.')+1) AS r1 FROM (SELECT NEW.subnet AS s)))))) IS NOT NULL
  );
END;

CREATE TRIGGER "Network_scoped_subnet_conflict_update"
BEFORE UPDATE OF subnet, site_id, vlan_id ON "Network"
  WHEN OLD.site_id IS NOT NEW.site_id OR OLD.vlan_id IS NOT NEW.vlan_id OR (SELECT CASE WHEN (s GLOB '[0-9]*.[0-9]*.[0-9]*.[0-9]*/[0-9]*' AND s NOT GLOB '*[^0-9./]*' AND s NOT GLOB '*..*' AND s NOT GLOB '*./*' AND s NOT GLOB '*/*[./]*' AND length(s)-length(replace(s,'.',''))=3 AND length(s)-length(replace(s,'/',''))=1 AND o1 <> '' AND o2 <> '' AND o3 <> '' AND o4 <> '' AND o1 = CAST(CAST(o1 AS INTEGER) AS TEXT) AND o2 = CAST(CAST(o2 AS INTEGER) AS TEXT) AND o3 = CAST(CAST(o3 AS INTEGER) AS TEXT) AND o4 = CAST(CAST(o4 AS INTEGER) AS TEXT) AND length(o1)<=3 AND length(o2)<=3 AND length(o3)<=3 AND length(o4)<=3 AND CAST(o1 AS INTEGER)<=255 AND CAST(o2 AS INTEGER)<=255 AND CAST(o3 AS INTEGER)<=255 AND CAST(o4 AS INTEGER)<=255 AND p<=32) THEN (((CAST(o1 AS INTEGER)*16777216+CAST(o2 AS INTEGER)*65536+CAST(o3 AS INTEGER)*256+CAST(o4 AS INTEGER)) & ((4294967295 << (32-p)) & 4294967295))*64+p) END FROM (SELECT s, o1, o2, o3, substr(r3,1,instr(r3,'/')-1) AS o4, CAST(substr(r3,instr(r3,'/')+1) AS INTEGER) AS p FROM (SELECT s, o1, o2, substr(r2,1,instr(r2,'.')-1) AS o3, substr(r2,instr(r2,'.')+1) AS r3 FROM (SELECT s, o1, r1, substr(r1,1,instr(r1,'.')-1) AS o2, substr(r1,instr(r1,'.')+1) AS r2 FROM (SELECT s, substr(s,1,instr(s,'.')-1) AS o1, substr(s,instr(s,'.')+1) AS r1 FROM (SELECT OLD.subnet AS s)))))) IS NOT (SELECT CASE WHEN (s GLOB '[0-9]*.[0-9]*.[0-9]*.[0-9]*/[0-9]*' AND s NOT GLOB '*[^0-9./]*' AND s NOT GLOB '*..*' AND s NOT GLOB '*./*' AND s NOT GLOB '*/*[./]*' AND length(s)-length(replace(s,'.',''))=3 AND length(s)-length(replace(s,'/',''))=1 AND o1 <> '' AND o2 <> '' AND o3 <> '' AND o4 <> '' AND o1 = CAST(CAST(o1 AS INTEGER) AS TEXT) AND o2 = CAST(CAST(o2 AS INTEGER) AS TEXT) AND o3 = CAST(CAST(o3 AS INTEGER) AS TEXT) AND o4 = CAST(CAST(o4 AS INTEGER) AS TEXT) AND length(o1)<=3 AND length(o2)<=3 AND length(o3)<=3 AND length(o4)<=3 AND CAST(o1 AS INTEGER)<=255 AND CAST(o2 AS INTEGER)<=255 AND CAST(o3 AS INTEGER)<=255 AND CAST(o4 AS INTEGER)<=255 AND p<=32) THEN (((CAST(o1 AS INTEGER)*16777216+CAST(o2 AS INTEGER)*65536+CAST(o3 AS INTEGER)*256+CAST(o4 AS INTEGER)) & ((4294967295 << (32-p)) & 4294967295))*64+p) END FROM (SELECT s, o1, o2, o3, substr(r3,1,instr(r3,'/')-1) AS o4, CAST(substr(r3,instr(r3,'/')+1) AS INTEGER) AS p FROM (SELECT s, o1, o2, substr(r2,1,instr(r2,'.')-1) AS o3, substr(r2,instr(r2,'.')+1) AS r3 FROM (SELECT s, o1, r1, substr(r1,1,instr(r1,'.')-1) AS o2, substr(r1,instr(r1,'.')+1) AS r2 FROM (SELECT s, substr(s,1,instr(s,'.')-1) AS o1, substr(s,instr(s,'.')+1) AS r1 FROM (SELECT NEW.subnet AS s))))))
BEGIN
  SELECT RAISE(ABORT, 'NETWORK_SUBNET_CONFLICT')
  WHERE EXISTS (
    SELECT 1 FROM "Network" n
    WHERE n.id <> NEW.id AND n.site_id = NEW.site_id AND n.vlan_id IS NEW.vlan_id
      AND (SELECT CASE WHEN (s GLOB '[0-9]*.[0-9]*.[0-9]*.[0-9]*/[0-9]*' AND s NOT GLOB '*[^0-9./]*' AND s NOT GLOB '*..*' AND s NOT GLOB '*./*' AND s NOT GLOB '*/*[./]*' AND length(s)-length(replace(s,'.',''))=3 AND length(s)-length(replace(s,'/',''))=1 AND o1 <> '' AND o2 <> '' AND o3 <> '' AND o4 <> '' AND o1 = CAST(CAST(o1 AS INTEGER) AS TEXT) AND o2 = CAST(CAST(o2 AS INTEGER) AS TEXT) AND o3 = CAST(CAST(o3 AS INTEGER) AS TEXT) AND o4 = CAST(CAST(o4 AS INTEGER) AS TEXT) AND length(o1)<=3 AND length(o2)<=3 AND length(o3)<=3 AND length(o4)<=3 AND CAST(o1 AS INTEGER)<=255 AND CAST(o2 AS INTEGER)<=255 AND CAST(o3 AS INTEGER)<=255 AND CAST(o4 AS INTEGER)<=255 AND p<=32) THEN (((CAST(o1 AS INTEGER)*16777216+CAST(o2 AS INTEGER)*65536+CAST(o3 AS INTEGER)*256+CAST(o4 AS INTEGER)) & ((4294967295 << (32-p)) & 4294967295))*64+p) END FROM (SELECT s, o1, o2, o3, substr(r3,1,instr(r3,'/')-1) AS o4, CAST(substr(r3,instr(r3,'/')+1) AS INTEGER) AS p FROM (SELECT s, o1, o2, substr(r2,1,instr(r2,'.')-1) AS o3, substr(r2,instr(r2,'.')+1) AS r3 FROM (SELECT s, o1, r1, substr(r1,1,instr(r1,'.')-1) AS o2, substr(r1,instr(r1,'.')+1) AS r2 FROM (SELECT s, substr(s,1,instr(s,'.')-1) AS o1, substr(s,instr(s,'.')+1) AS r1 FROM (SELECT n.subnet AS s)))))) IS (SELECT CASE WHEN (s GLOB '[0-9]*.[0-9]*.[0-9]*.[0-9]*/[0-9]*' AND s NOT GLOB '*[^0-9./]*' AND s NOT GLOB '*..*' AND s NOT GLOB '*./*' AND s NOT GLOB '*/*[./]*' AND length(s)-length(replace(s,'.',''))=3 AND length(s)-length(replace(s,'/',''))=1 AND o1 <> '' AND o2 <> '' AND o3 <> '' AND o4 <> '' AND o1 = CAST(CAST(o1 AS INTEGER) AS TEXT) AND o2 = CAST(CAST(o2 AS INTEGER) AS TEXT) AND o3 = CAST(CAST(o3 AS INTEGER) AS TEXT) AND o4 = CAST(CAST(o4 AS INTEGER) AS TEXT) AND length(o1)<=3 AND length(o2)<=3 AND length(o3)<=3 AND length(o4)<=3 AND CAST(o1 AS INTEGER)<=255 AND CAST(o2 AS INTEGER)<=255 AND CAST(o3 AS INTEGER)<=255 AND CAST(o4 AS INTEGER)<=255 AND p<=32) THEN (((CAST(o1 AS INTEGER)*16777216+CAST(o2 AS INTEGER)*65536+CAST(o3 AS INTEGER)*256+CAST(o4 AS INTEGER)) & ((4294967295 << (32-p)) & 4294967295))*64+p) END FROM (SELECT s, o1, o2, o3, substr(r3,1,instr(r3,'/')-1) AS o4, CAST(substr(r3,instr(r3,'/')+1) AS INTEGER) AS p FROM (SELECT s, o1, o2, substr(r2,1,instr(r2,'.')-1) AS o3, substr(r2,instr(r2,'.')+1) AS r3 FROM (SELECT s, o1, r1, substr(r1,1,instr(r1,'.')-1) AS o2, substr(r1,instr(r1,'.')+1) AS r2 FROM (SELECT s, substr(s,1,instr(s,'.')-1) AS o1, substr(s,instr(s,'.')+1) AS r1 FROM (SELECT NEW.subnet AS s))))))
      AND (SELECT CASE WHEN (s GLOB '[0-9]*.[0-9]*.[0-9]*.[0-9]*/[0-9]*' AND s NOT GLOB '*[^0-9./]*' AND s NOT GLOB '*..*' AND s NOT GLOB '*./*' AND s NOT GLOB '*/*[./]*' AND length(s)-length(replace(s,'.',''))=3 AND length(s)-length(replace(s,'/',''))=1 AND o1 <> '' AND o2 <> '' AND o3 <> '' AND o4 <> '' AND o1 = CAST(CAST(o1 AS INTEGER) AS TEXT) AND o2 = CAST(CAST(o2 AS INTEGER) AS TEXT) AND o3 = CAST(CAST(o3 AS INTEGER) AS TEXT) AND o4 = CAST(CAST(o4 AS INTEGER) AS TEXT) AND length(o1)<=3 AND length(o2)<=3 AND length(o3)<=3 AND length(o4)<=3 AND CAST(o1 AS INTEGER)<=255 AND CAST(o2 AS INTEGER)<=255 AND CAST(o3 AS INTEGER)<=255 AND CAST(o4 AS INTEGER)<=255 AND p<=32) THEN (((CAST(o1 AS INTEGER)*16777216+CAST(o2 AS INTEGER)*65536+CAST(o3 AS INTEGER)*256+CAST(o4 AS INTEGER)) & ((4294967295 << (32-p)) & 4294967295))*64+p) END FROM (SELECT s, o1, o2, o3, substr(r3,1,instr(r3,'/')-1) AS o4, CAST(substr(r3,instr(r3,'/')+1) AS INTEGER) AS p FROM (SELECT s, o1, o2, substr(r2,1,instr(r2,'.')-1) AS o3, substr(r2,instr(r2,'.')+1) AS r3 FROM (SELECT s, o1, r1, substr(r1,1,instr(r1,'.')-1) AS o2, substr(r1,instr(r1,'.')+1) AS r2 FROM (SELECT s, substr(s,1,instr(s,'.')-1) AS o1, substr(s,instr(s,'.')+1) AS r1 FROM (SELECT NEW.subnet AS s)))))) IS NOT NULL
  );
END;

CREATE TRIGGER "IpAllocation_unique_ip_insert"
BEFORE INSERT ON "IpAllocation"
BEGIN
  SELECT RAISE(ABORT, 'IP_ALLOCATION_CONFLICT')
  WHERE EXISTS (
    SELECT 1 FROM "IpAllocation" a
    WHERE a.id <> NEW.id AND a.network_id = NEW.network_id AND a.ip_address = NEW.ip_address
  );
END;

CREATE TRIGGER "IpAllocation_unique_ip_update"
BEFORE UPDATE OF network_id, ip_address ON "IpAllocation"
  WHEN OLD.network_id IS NOT NEW.network_id OR OLD.ip_address IS NOT NEW.ip_address
BEGIN
  SELECT RAISE(ABORT, 'IP_ALLOCATION_CONFLICT')
  WHERE EXISTS (
    SELECT 1 FROM "IpAllocation" a
    WHERE a.id <> NEW.id AND a.network_id = NEW.network_id AND a.ip_address = NEW.ip_address
  );
END;
